    const notice = notifications.length === 0 && mainNotifications.length === 0 ? undefined : this.notificationText(handle.agent, notifications, member.memberId, mainNotifications, undefined, text)

import { readFile } from 'node:fs/promises'

const usage = 'Usage: node scripts/team-performance/compare-team-performance.mjs [--json] [--max-regression <percent>] <before-summary-or-matrix> <after-summary-or-matrix>'
const rawArgs = process.argv.slice(2)
const json = rawArgs.includes('--json')
const args = rawArgs.filter(value => value !== '--json')
let maxRegression
const positional = []
for (let index = 0; index < args.length; index += 1) {
  const value = args[index]
  if (value === '--max-regression') {
    const next = args[++index]
    maxRegression = Number(next)
  } else if (value.startsWith('--max-regression=')) {
    maxRegression = Number(value.slice('--max-regression='.length))
  } else {
    positional.push(value)
  }
}
if (positional.length !== 2 || (maxRegression !== undefined && (!Number.isFinite(maxRegression) || maxRegression < 0))) {
  console.error(usage)
  process.exit(2)
}

async function readJson(path) {
  return JSON.parse(await readFile(path, 'utf8'))
}

function summaryEntries(document, source) {
  if (Array.isArray(document.summary)) return document.summary.map(entry => ({ key: entry.scenario, summary: entry }))
  if (Array.isArray(document.results)) {
    return document.results.flatMap(result => {
      const summaries = result.summary?.summary
      if (!Array.isArray(summaries)) return []
      const key = `${result.scenario}:${result.threads}:${result.followers}`
      return summaries.map(summary => ({ key, summary }))
    })
  }
  throw new Error(`${source} is neither a run summary.json nor a matrix results.json`)
}

async function load(path) {
  return summaryEntries(await readJson(path), path)
}

function metricRows(beforeEntries, afterEntries) {
  const before = new Map(beforeEntries.map(entry => [entry.key, entry.summary]))
  const after = new Map(afterEntries.map(entry => [entry.key, entry.summary]))
  const rows = []
  const missingInAfter = []
  const missingInBefore = []
  for (const [key, beforeSummary] of before) {
    const afterSummary = after.get(key)
    if (afterSummary === undefined) continue
    const metrics = new Set([...Object.keys(beforeSummary.metrics ?? {}), ...Object.keys(afterSummary.metrics ?? {})])
    for (const metric of metrics) {
      const inBefore = beforeSummary.metrics?.[metric] !== undefined
      const inAfter = afterSummary.metrics?.[metric] !== undefined
      if (inBefore && !inAfter) missingInAfter.push({ key, metric })
      if (!inBefore && inAfter) missingInBefore.push({ key, metric })
    }
    for (const metric of metrics) {
      for (const percentile of ['p50', 'p95', 'p99']) {
        const beforeValue = beforeSummary.metrics?.[metric]?.[percentile]
        const afterValue = afterSummary.metrics?.[metric]?.[percentile]
        if (typeof beforeValue !== 'number' || typeof afterValue !== 'number') continue
        const deltaMs = afterValue - beforeValue
        const deltaPercent = beforeValue === 0 ? null : (deltaMs / beforeValue) * 100
        rows.push({ key, metric, percentile, before: beforeValue, after: afterValue, deltaMs, deltaPercent })
      }
    }
  }
  return { rows, missingInAfter, missingInBefore }
}

const beforeEntries = await load(positional[0])
const afterEntries = await load(positional[1])
const beforeKeys = new Set(beforeEntries.map(entry => entry.key))
const afterKeys = new Set(afterEntries.map(entry => entry.key))
const metricComparison = metricRows(beforeEntries, afterEntries)
const { rows } = metricComparison
const regressions = maxRegression === undefined
  ? []
  : rows.filter(row => row.deltaPercent !== null && row.deltaPercent > maxRegression)
const report = {
  before: positional[0],
  after: positional[1],
  maxRegressionPercent: maxRegression ?? null,
  missingInAfter: [...beforeKeys].filter(key => !afterKeys.has(key)),
  missingInBefore: [...afterKeys].filter(key => !beforeKeys.has(key)),
  missingMetricsInAfter: metricComparison.missingInAfter,
  missingMetricsInBefore: metricComparison.missingInBefore,
  rows,
  regressions,
}

if (json) {
  console.log(JSON.stringify(report, null, 2))
} else {
  console.log(`before: ${report.before}`)
  console.log(`after:  ${report.after}`)
  if (report.missingInAfter.length > 0) console.log(`missing in after: ${report.missingInAfter.join(', ')}`)
  if (report.missingInBefore.length > 0) console.log(`missing in before: ${report.missingInBefore.join(', ')}`)
  if (report.missingMetricsInAfter.length > 0) console.log(`missing metrics in after: ${report.missingMetricsInAfter.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
  if (report.missingMetricsInBefore.length > 0) console.log(`missing metrics in before: ${report.missingMetricsInBefore.map(entry => `${entry.key}.${entry.metric}`).join(', ')}`)
  for (const row of rows) {
    const delta = row.deltaPercent === null ? 'n/a' : `${row.deltaPercent >= 0 ? '+' : ''}${row.deltaPercent.toFixed(1)}%`
    console.log(`${row.key} ${row.metric}.${row.percentile}: ${row.before.toFixed(3)}ms -> ${row.after.toFixed(3)}ms (${delta})`)
  }
  if (maxRegression !== undefined) console.log(`regressions over ${maxRegression}%: ${regressions.length}`)
}
if (maxRegression !== undefined && (regressions.length > 0 || report.missingInAfter.length > 0 || report.missingInBefore.length > 0
  || report.missingMetricsInAfter.length > 0 || report.missingMetricsInBefore.length > 0)) process.exitCode = 1

async function toolSample(sample: number, commits: { team: string; harness: string }): Promise<Sample> {
  const startedAt = new Date().toISOString()
  const host = await mount()
  const adapter = new EmptyAdapter()
  const releaseAdapter = host.ctx.llm.registerAdapter(['mock'], adapter)
  try {
    const member = await addMember(host.ctx, `baseline-tool-${sample}`)
    const team = host.ctx.agentTeam as any
    let hostViewMs: number | null = null
    const originalView = team.viewForAgent.bind(team)
    team.viewForAgent = (...args: unknown[]) => {
      const begin = now()
      try { return originalView(...args) } finally { hostViewMs = elapsed(begin) }
    }
    const begin = now()
    const result = await host.ctx.tools.execute({ signal: new AbortController().signal, callId: ToolCallId(`baseline-view-${sample}`),
      name: 'team_view', arguments: {}, agent: member.agent })
    const total = elapsed(begin)
    if (result.isError) throw new Error(`team_view baseline failed: ${JSON.stringify(result)}`)
    return {
      runId, scenario: 'tool-call', sample, phase: sample === 0 ? 'warmup' : 'measure', startedAt: startedAt, teamCommit: commits.team, harnessCommit: commits.harness,
      node: process.version, workload: { tool: 'team_view', memberCount: 1, action: 'read' },
      stages: { toolTotalMs: total, hostViewMs, clientMs: null }, ids: { requestId: null, operationId: null, noticeMessageId: null, callId: `baseline-view-${sample}`, turnId: null, agentSessionId: member.agent.id }, counters: { resultBytes: Buffer.byteLength(JSON.stringify(result)) },
    }
  } finally {
    releaseAdapter()
    await host.dispose()
  }
}

async function toolReadSweepSample(sample: number, commits: { team: string; harness: string }): Promise<Sample> {
  const startedAt = new Date().toISOString()
  const host = await mount()
  const adapter = new EmptyAdapter()
  const releaseAdapter = host.ctx.llm.registerAdapter(['mock'], adapter)
  try {
    const member = await addMember(host.ctx, `baseline-tool-sweep-${sample}`)
    const project = await host.ctx.agentTeam.createProject({ requestId: requestId(`baseline:tool-sweep-project:${sample}`), workspaceId,
      name: 'tool-read-sweep', description: 'Tool read performance benchmark' })
    const projectMember = await addMember(host.ctx, `baseline-tool-sweep-project-member-${sample}`, project.project.projectRef)
    const started = await host.ctx.agentTeam.startThread({ kind: 'discussion', requestId: requestId(`baseline:tool-sweep-thread:${sample}`), workspaceId,
      projectRef: project.project.projectRef, body: 'Tool read sweep Thread' })
    if (started.kind !== 'committed') throw new Error(`tool-read-sweep Thread did not commit: ${started.kind}`)
    const calls = [
      { name: 'team_inbox', arguments: {} },
      { name: 'team_task', arguments: { action: 'board' } },
      { name: 'team_view', arguments: {} },
      { name: 'team_attention', arguments: { action: 'status', threadRef: started.thread.threadRef } },
      { name: 'team_thread', arguments: { action: 'read', threadRef: started.thread.threadRef } },
    ] as const
    const stages: Record<string, number> = {}
    const counters: Record<string, number> = {}
    const begin = now()
    for (const [index, call] of calls.entries()) {
      const callBegin = now()
      const agent = call.name === 'team_inbox' || call.name === 'team_task' || call.name === 'team_view' ? member.agent : projectMember.agent
      const result = await host.ctx.tools.execute({ signal: new AbortController().signal,
        callId: ToolCallId(`baseline-sweep-${sample}-${index}`), name: call.name, arguments: call.arguments, agent })
      stages[`${call.name}Ms`] = elapsed(callBegin)
      if (result.isError) throw new Error(`${call.name} baseline failed: ${JSON.stringify(result)}`)
      counters[`${call.name}ResultBytes`] = Buffer.byteLength(JSON.stringify(result))
    }
    return { runId, scenario: 'tool-read-sweep', sample, phase: sample === 0 ? 'warmup' : 'measure', startedAt,
      teamCommit: commits.team, harnessCommit: commits.harness, node: process.version,
      workload: { tools: calls.map(call => call.name), memberCount: 2, action: 'read' },
      stages: { toolSweepMs: elapsed(begin), ...stages }, ids: { requestId: null, operationId: null, noticeMessageId: null, turnId: null, agentSessionId: member.agent.id }, counters }
  } finally {
    releaseAdapter()
    await host.dispose()
  }
}

async function threadReadReplySample(sample: number, commits: { team: string; harness: string }): Promise<Sample> {
